# label: (def, aliases, extra look, use, not, sources)
GIVE = "Give it room, keep dogs leashed, and never feed it."
ANIMALS = {
"white_tailed_deer": ("The white-tailed deer is the common deer of the East, brown with a white belly and a tail it raises like a white flag when alarmed.", ["whitetail", "white-tail deer", "deer", "buck", "doe"], ["bucks carry antlers from late summer to winter"], "Deer are the main big-game animal in New England; check your state's season and tag rules before hunting.", "Do not approach a fawn lying alone; the doe is usually nearby. Watch for deer on roads at dawn and dusk.", ["fws", "state-regs-link"]),
"moose": ("The moose is the largest deer, with a long face, a hanging dewlap, and broad flat antlers on bulls.", ["Alces", "bull moose", "cow moose"], ["dark body on long pale legs"], "Watch from at least 50 yards (about 45 m). If one lays its ears back or raises its hackles, back away and put a tree between you.", "Do not approach a cow with a calf or a bull in fall rut. Moose cause serious crashes at night on Maine roads.", ["nps", "fws"]),
"elk": ("The elk is a large deer with a pale rump, a dark neck, and branching antlers on bulls.", ["wapiti", "Cervus canadensis", "bull elk"], ["bugling calls in fall"], "Elk are rare in New England; a big brown deer there is more likely a moose or white-tailed deer.", "Do not approach; bulls in rut and cows with calves charge.", ["nps", "fws"]),
"black_bear": ("The black bear is the only bear in the East, black or brown, with a straight face profile and no shoulder hump.", ["bear", "American black bear", "Ursus americanus"], ["tall pointed ears", "short curved claws"], "Make noise on the trail, store food and trash away from camp, and if you meet one, stand tall, talk firmly, and back away slowly.", "Never run or climb a tree to escape. If a black bear attacks, fight back.", ["nps", "fws"]),
"coyote": ("The eastern coyote is a slim, dog-like wild canine with a bushy tail carried low and pointed ears.", ["eastern coyote", "coywolf", "Canis latrans", "brush wolf"], ["yips and howls at night"], "If one comes close, make yourself big, shout, and throw something toward it.", "Do not run, and do not leave food or pet food outside.", ["fws", "nps"]),
"red_fox": ("The red fox is a small wild canine with a red coat, black legs, and a white tail tip.", ["fox", "Vulpes vulpes"], ["bushy tail longer than half its body"], "Watch from a distance; foxes are usually shy.", "A fox that is bold, stumbling, or aggressive may have rabies; leave it and report it.", ["cdc", "fws"]),
"bobcat": ("The bobcat is a medium wild cat with a short bobbed tail, tufted ears, and a spotted coat.", ["wildcat", "Lynx rufus", "bay lynx"], ["tail tip black on top, white below"], "Bobcats avoid people; enjoy the sighting from where you are.", "Do not corner one, and treat a bold, unafraid bobcat as possibly rabid.", ["fws", "cdc"]),
"porcupine": ("The porcupine is a slow, round rodent covered in barbed quills.", ["porky", "Erethizon dorsatum", "quill pig"], ["chewed bark high on trees"], "Leave it alone and keep dogs away. A pet with quills needs a vet.", "It cannot throw quills, but it will swing its tail. Do not pull quills with bare fingers.", ["nps", "fws"]),
"raccoon": ("The raccoon is a gray, masked, ring-tailed animal that raids camps and trash at night.", ["coon", "Procyon lotor", "trash panda"], ["handprint-like tracks near water"], "Lock food away at night and keep a clean camp.", "A raccoon active in daylight, stumbling or unafraid may have rabies; leave it and report it.", ["cdc", "nps"]),
"striped_skunk": ("The striped skunk is a black animal with white stripes down its back that sprays a strong musk when threatened.", ["skunk", "Mephitis"], ["stamps its feet and raises its tail before spraying"], "Back away slowly if it stamps or turns.", "A skunk out in daylight acting oddly may have rabies.", ["cdc", "nps"]),
"beaver": ("The beaver is a large water rodent with a flat paddle tail that builds dams and lodges.", ["American beaver", "Castor canadensis"], ["tooth-chewed pointed stumps near water"], "Beaver ponds flood trails and make routes longer; plan around them.", "Treat water near beaver ponds before drinking; it often carries Giardia (\"beaver fever\").", ["cdc", "fws"]),
"snowshoe_hare": ("The snowshoe hare is a northern hare with huge furry hind feet whose coat turns white in winter.", ["varying hare", "Lepus americanus", "snowshoe rabbit"], ["brown in summer, white in winter"], "Hares are legal small game in many states; check your state's rules.", "Wear gloves when cleaning any rabbit or hare and cook it through, because of tularemia.", ["cdc", "state-regs-link"]),
"wild_turkey": ("The wild turkey is a large dark bird with a bare red-blue head and a fanned tail.", ["turkey", "Meleagris gallopavo", "gobbler", "tom turkey"], ["toms gobble in spring"], "Turkey season has its own rules; identify the bird and what is beyond it before every shot.", "Do not wear red, white, or blue in spring turkey woods; those are a gobbler's colors.", ["fws", "state-regs-link"]),
"ruffed_grouse": ("The ruffed grouse is a brown or gray barred woodland bird with a fan tail and a dark neck ruff.", ["partridge", "Bonasa umbellus", "grouse", "pa'tridge"], ["drumming sound like a starting engine in spring"], "Grouse are upland game in New England; check season rules.", "Cook game birds through.", ["fws", "state-regs-link"]),
"bald_eagle": ("The bald eagle is a large raptor whose adults have a white head and tail and a yellow bill.", ["eagle", "Haliaeetus leucocephalus", "American eagle"], ["young birds are mottled brown for four years"], "Watch and photograph from a distance, especially near nests.", "Bald eagles and their feathers are protected by federal law; do not disturb, collect, or harm them.", ["fws"]),
"great_horned_owl": ("The great horned owl is a large owl with ear tufts, yellow eyes, and a deep hooting call.", ["hoot owl", "Bubo virginianus", "cat owl"], ["white throat patch"], "Enjoy it from a distance, especially near nests in late winter.", "Owls are federally protected; do not disturb, collect, or harm them.", ["fws"]),
"canada_goose": ("The Canada goose is a large goose with a black neck and head and a white chin strap.", ["honker", "Branta canadensis", "goose"], ["V-shaped flocks with loud honking"], "Geese are migratory birds with federal and state season rules; check both.", "Geese defend nests and goslings by charging; give them room.", ["fws", "state-regs-link"]),
"rattlesnake": ("The timber rattlesnake is a heavy-bodied venomous snake with a broad triangular head and a rattle on its tail.", ["timber rattlesnake", "rattler", "Crotalus horridus"], ["dark crossbands on a yellow or dark body"], "Rattlesnakes are rare and protected in much of New England. Back away slowly and walk around.", "Do not handle, kill, or pin it. After a bite, call 911, keep the person still and calm, and do not cut, suck, or tourniquet the bite.", ["cdc", "nps"]),
"copperhead": ("The copperhead is a venomous snake with a copper-colored head and tan hourglass bands.", ["Agkistrodon contortrix", "highland moccasin"], ["bands narrow on the back and wide on the sides"], "Copperheads live in southern New England's rocky woods. Back away slowly.", "Do not handle it. After a bite, call 911, keep still, and do not cut, suck, or ice the bite.", ["cdc", "nps"]),
"cottonmouth": ("The cottonmouth is a heavy, dark venomous water snake that gapes to show a white mouth.", ["water moccasin", "Agkistrodon piscivorus"], ["swims with its body high on the water"], "Cottonmouths do not live in New England; a dark snake in water there is almost always a northern water snake.", "Do not handle any snake you cannot identify. After a bite, call 911 and keep still.", ["cdc", "nps"]),
"eastern_garter_snake": ("The eastern garter snake is a slim, harmless snake with three pale stripes along its body.", ["garter snake", "garden snake", "Thamnophis sirtalis"], ["often basks on paths and rocks"], "It is harmless; let it go on its way.", "Do not grab it; it may bite and release musk.", ["nps"]),
"northern_water_snake": ("The northern water snake is a common, non-venomous banded brown snake found in and near water.", ["water snake", "Nerodia sipedon"], ["round pupils"], "It is not venomous; give it room.", "It bites hard if handled, and it is often mistaken for a copperhead or cottonmouth.", ["nps"]),
"blacklegged_tick": ("The blacklegged tick, or deer tick, is a tiny dark tick that spreads Lyme disease, anaplasmosis, and babesiosis.", ["deer tick", "Ixodes scapularis", "Lyme tick"], ["nymphs are the size of a poppy seed"], "Check your whole body after time outside, and remove ticks with fine tweezers pulled straight out.", "Do not twist, burn, or smother a tick. See a clinician for a spreading rash or fever after a bite.", ["cdc"]),
"american_dog_tick": ("The American dog tick is a larger brown tick with cream markings that can carry Rocky Mountain spotted fever.", ["dog tick", "wood tick", "Dermacentor variabilis"], ["common in grassy fields and trail edges"], "Remove it with fine tweezers close to the skin and wash the bite.", "See a clinician for fever, rash, or headache in the two weeks after a bite.", ["cdc"]),
"lone_star_tick": ("The lone star tick is a reddish-brown tick whose females have one white dot on the back; its bites are linked to a red-meat allergy.", ["Amblyomma americanum", "turkey tick"], ["aggressive biter, spreading north"], "Remove it with fine tweezers close to the skin.", "See a clinician for fever or rash after a bite, or hives hours after eating red meat.", ["cdc"]),
"black_widow": ("The black widow is a shiny black spider with a red hourglass under its belly whose bite needs medical care.", ["widow spider", "Latrodectus"], ["messy webs under rocks, logs, and outhouse seats"], "Shake out gloves, boots, and firewood before use.", "After a bite, clean it, apply a cool pack, and get medical care, especially for cramps or trouble breathing.", ["cdc"]),
"bald_faced_hornet": ("The bald-faced hornet is a black-and-white wasp that builds a gray paper nest in trees and defends it fiercely.", ["white-faced hornet", "Dolichovespula maculata"], ["nests hang from branches or eaves"], "Walk wide around nests.", "Call 911 for swelling of the face or throat, or trouble breathing after a sting.", ["cdc"]),
"yellowjacket": ("The yellowjacket is a black-and-yellow wasp that nests in the ground and stings repeatedly.", ["yellow jacket", "ground wasp", "Vespula"], ["busy hole in the ground"], "Watch for ground nests when clearing a camp or trail.", "Call 911 for swelling of the face or throat, or trouble breathing after a sting.", ["cdc"]),
"wild_boar": ("The wild boar, or feral hog, is a dark bristly pig with a long snout that can be aggressive.", ["feral hog", "feral pig", "wild pig", "Sus scrofa"], ["rooted-up ground"], "Feral hogs are not established in New England; report one to your state wildlife agency.", "Cook the meat fully, and wear gloves when cleaning; hogs can carry brucellosis.", ["cdc", "state-regs-link"]),
}
